var a=`0053-kulajda`;var i=`world-0053`;var n=`CZ`;var s=`eastern-europe`;var o=4;var r=36;var l={en:`Kulajda`,ua:`Кулайда`};var u={en:`A classic dish from Czechia, featuring potato, button mushroom, heavy cream, dill. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Чехія. Основні складники: картопля, печериця, вершки високої жирності, кріп. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 12 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 12 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:12,i:[[`water`,900,`ml`],[`potato`,350,`g`],[`caraway-seeds`,3,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`button-mushroom`,280,`g`],[`unsalted-butter`,35,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:8,i:[[`heavy-cream`,230,`ml`],[`dill`,25,`g`],[`apple-cider-vinegar`,15,`ml`],[`white-granulated-sugar`,12,`g`],[`table-salt`,null,`to_taste`]]},{en:`Boil the eggs for about 8 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 8 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:8,i:[[`chicken-egg`,4,`pcs`]]}];var m={slug:a,id:i,country:`CZ`,region:s,servings:4,minutes:36,title:l,text:u,steps:g};export{n as country,m as default,i as id,r as minutes,s as region,o as servings,a as slug,g as steps,u as text,l as title};